import {maximumWarriorCheckpoint} from './compact-checkpoint-fixture.mjs';import {writeChunk,writeCrossChunks,stateHash} from '../../src/challenge/room-checkpoint.ts';
export async function maximumDueFixture(){const {f,h,cp,scene}=await maximumWarriorCheckpoint();for(const name of ['cross','bengshan','earth'])scene[name].effects=scene[name].effects.filter(e=>e.targetIndex<=5).map(e=>({...e,originUs:{n:'0',d:'1'},nextJump:0,budget:'5',snapshot:{...e.snapshot,haste:{n:'1',d:'1'},crit:{n:'0',d:'1'}}}));for(const enemy of scene.enemies){enemy.actor.hp='1000000000000';enemy.actor.maxHp='1000000000000';}for(const target of scene.combat.targets){target.hp='1000000000000';target.maxHp='1000000000000';}const current=await f.cp(),chunks=[await writeChunk(h,0,2,cp.role),await writeChunk(h,1,2,scene),...await writeCrossChunks(h,scene.cross,current.header.activeChunks,scene.bengshan,scene.badao,scene.earth,current.effectChunks)];await f.store.run(async tx=>{for(const c of chunks)tx.set(c.id,c);tx.set(current.header.id,{...current.header,activeChunks:chunks.map(c=>({ordinal:c.ordinal,chunkRevision:c.chunkRevision,hash:c.hash,sceneEpoch:c.sceneEpoch})),state:{...current.header.state,publicStateHash:await stateHash(cp.role,scene)}});});f.clock.now=()=>2013;return f;}
